#version 300 es
precision highp float;

// VisualSynth uniforms
uniform float uTime;
uniform float uFrame;
uniform float uFps;
uniform float uRms;

// Audio uniforms
uniform float audioLow;
uniform float audioLowSmooth;
uniform float audioMid;
uniform float audioMidSmooth;
uniform float audioHigh;
uniform float audioHighSmooth;

// Screen uniforms
uniform float uAspectX;
uniform float uAspectY;
uniform vec2 uAspect;
uniform vec2 uTexSize;
#define texsize vec4(uTexSize, 1.0/uTexSize)

// Random values
uniform vec2 uRandomPreset;
uniform vec2 uRandomFrame;
uniform vec4 rand_preset;
uniform vec4 rand_frame;

// Input from vertex shader
in vec2 vUv;
in vec2 vUvOriginal;
in float vRadius;
in float vAngle;

// Output
out vec4 fragColor;

// Textures
uniform sampler2D sampler_main;
uniform sampler2D sampler_noise_lq;
uniform sampler2D sampler_noise_mq;
uniform sampler2D sampler_noise_hq;
uniform sampler2D sampler_blur1;
uniform sampler2D sampler_blur2;
uniform sampler2D sampler_blur3;
#define sampler_fc_main sampler_main
#define sampler_pc_main sampler_main
#define sampler_fw_main sampler_main
#define sampler_pw_main sampler_main
#define sampler_noise_lq_lite sampler_noise_lq
#define sampler_noisevol_lq sampler_noise_lq
#define sampler_noisevol_hq sampler_noise_hq

// MilkDrop q-variable uniforms (q1–q32)
uniform float q1; uniform float q2; uniform float q3; uniform float q4;
uniform float q5; uniform float q6; uniform float q7; uniform float q8;
uniform float q9; uniform float q10; uniform float q11; uniform float q12;
uniform float q13; uniform float q14; uniform float q15; uniform float q16;
uniform float q17; uniform float q18; uniform float q19; uniform float q20;
uniform float q21; uniform float q22; uniform float q23; uniform float q24;
uniform float q25; uniform float q26; uniform float q27; uniform float q28;
uniform float q29; uniform float q30; uniform float q31; uniform float q32;

// MilkDrop _c / _q matrix uniforms
uniform vec4 _c0; uniform vec4 _c1; uniform vec4 _c2; uniform vec4 _c3;
uniform vec4 _c4; uniform vec4 _c5; uniform vec4 _c6; uniform vec4 _c7;
uniform vec4 _c8; uniform vec4 _c9; uniform vec4 _c10; uniform vec4 _c11;
uniform vec4 _c12; uniform vec4 _c13; uniform vec4 _c14;
uniform vec4 _c15; uniform vec4 _c16; uniform vec4 _c17;
uniform vec4 _qa; uniform vec4 _qb; uniform vec4 _qc; uniform vec4 _qd;
uniform vec4 _qe; uniform vec4 _qf; uniform vec4 _qg; uniform vec4 _qh;

// MilkDrop rotation matrices
uniform mat4 rot_s1; uniform mat4 rot_s2; uniform mat4 rot_s3; uniform mat4 rot_s4;
uniform mat4 rot_d1; uniform mat4 rot_d2; uniform mat4 rot_d3; uniform mat4 rot_d4;
uniform mat4 rot_f1; uniform mat4 rot_f2; uniform mat4 rot_f3; uniform mat4 rot_f4;
uniform mat4 rot_vf1; uniform mat4 rot_vf2; uniform mat4 rot_vf3; uniform mat4 rot_vf4;
uniform mat4 rot_uf1; uniform mat4 rot_uf2; uniform mat4 rot_uf3; uniform mat4 rot_uf4;
uniform mat4 rot_rand1; uniform mat4 rot_rand2; uniform mat4 rot_rand3; uniform mat4 rot_rand4;

float clamp01(float x) { return clamp(x, 0.0, 1.0); }
vec2 clamp01(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 clamp01(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 clamp01(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }
float lum(vec3 x) { return dot(x, vec3(0.32, 0.49, 0.29)); }
float lum(vec4 x) { return dot(x.rgb, vec3(0.32, 0.49, 0.29)); }
float sat(float x) { return clamp(x, 0.0, 1.0); }
vec2 sat(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 sat(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 sat(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }

vec3 GetPixel(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec3 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv).xyz; }
vec3 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv).xyz; }
vec3 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv).xyz; }
vec4 noise3(vec2 uv) { return texture(sampler_noise_lq, uv); }
vec3 GetMain(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec2 multiply(vec2 v, mat2 m) { return m * v; }
vec3 multiply(vec3 v, mat3 m) { return m * v; }
vec4 multiply(vec4 v, mat4 m) { return m * v; }
vec4 textureBias(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
vec4 textureLod4(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
// Custom sampler stubs (mapped to noise texture)
#define sampler_sun sampler_noise_lq
#define sampler_colors14 sampler_noise_lq
#define sampler_pw_noise_lq sampler_noise_lq
sampler sampler_sun;
vec4 texsize_sun;
sampler sampler_colors14;
sampler sampler_pw_noise_lq;
vec2 rs2,rs0,rss;
float Dist(vec2 a, vec2 b)
{
return sqrt(pow(a.x-b.x, 2.0 ) + pow(a.y-b.y, 2.0 ));
}
float fract(float a)
{
return(a - floor(a));
}
vec2 fract(vec2 a)
{
vec2 b = vec2(fract(a.x), fract(a.y));
return b;
}
float Hash21(vec2 p)
{
p = fract(p * vec2(234.34, 435.345) );
p += dot(p, p + 34.24);
return fract(p.x*p.y + 0.0*abs(sin(cos(p.x*p.y))));
}
vec3 backstarsf(vec2 UV, float mult)
{
vec3 backstars = 0;
vec2 backstarsuv = UV;
backstarsuv.y *= -1;
backstarsuv *= mult;
vec2 gv = fract(backstarsuv) -0.5 ;
vec2 id = floor(backstarsuv);
float hash = Hash21(id);
float circlepos = hash;
float circle = Dist(gv,circlepos);
float circler = 0.05;
float star;
float smooth;
if(circle < circler)
{
smooth = hash * 2.0;
star = smoothstep(circler,circler - 0.05 - 0.0 * smooth, circle);
if(hash < 0.015) {backstars += vec3(star*0.3, 0.0 , 0.0 );}
else if(hash < 0.03) {backstars += vec3(star*0.3, 0.0 ,star);}
else if(hash < 0.05) {backstars += vec3(star,star*0.5, 0.0 );}
}
return backstars;
}
shader_body
{
ret = texture( sampler_main, uv ).xyz;
float a = uv.x;
float b = uv.y;
float ca;
float cb;
float golden = 1.6180339887;
// ca; 0       ; (golden - 2.0); 0.285; 0.285; 0.45  ; -0.70176; -0.835 ; -0.8 ; -0.7269
// cb; 1.0 - golden; (golden - 1.0); 0    ; 0.01 ; 0.1428; -0.3842 ; -0.2321; 0.156; 0.1889
if(q9 == 5){
ca = 0.285;
cb = 0;
}
else if(q9 == 6){
ca = -0.66176 + 0.03*sin(0.25*uTime + 0.014*q5);
cb = -0.3842;
}
// q9 does equal 7
else if(q9 == 7) {
ca = -0.7069 + 0.03*sin(0.2*uTime + 0.0*0.012*q5) ;
cb = 0.138 + 0.04*cos(uTime*0.4 + 0*0.03*q5);
}
else { // if q9 = 0
ca = a;
cb = b;
}
float aa;
float bb;
float n = 0;
float maxiter = 60;
float m=0;
float r = 1000;
float r2 = r*r;
vec3 col;
float pa;
float pb;
vec2 z;
vec2 pz;
float leaves = 0.4*(q5+q6+q7)*0.3; // speed for the leaves
while(n < maxiter && m==0)
{
aa = a*a - b*b;
bb = 2.0 * a*b;
pa = a;
pb = b;
pz = vec2(pa*cos(leaves*0.5) - pb*sin(leaves*0.5),pa*sin(leaves*0.5) + pb*cos(leaves*0.5));
a = aa + ca;
b = bb + cb;
z = vec2(a,b);
//if(sqrt(pow(a-pa, 2.0 ) + pow(b-pb, 2.0 )) > r2)
//if(dot(z,pz) > r2)
//if(sqrt(a*a + b*b) > r2)
if(dot(z + 4000.0*q25,pz + 60.0*q26) > r2)
{
m = 1;
}
else
{
n++;
}
}
col = texture(sampler_colors14, vec2(0.5 + 0.4*sin(n*0.4 + 0*0.2*uTime + 0.01*(q5+q6+q7)),0.5 + 0.4*cos(n*0.1 + 0*0.4*uTime + 0.015*(q5+q6+q7)))).xyz;
//col = pow(col, 6.0 );
//col*=40;
col = pow(col, 4.0 );
col*=2;
float beat = (q13 + q12 + q14) / 3.0;
col*= 0.3 + vec3(beat,beat,beat);
float dist = (sqrt(a*a + b*b));
float fraciter = (dist - r) / (r2 - r);
fraciter = log2(log(dist) / log(r)) ;
n -= fraciter;
vec3 color;
color.x = 0.5 + 0.5*sin(0.09*n*1.5 + 0*0.7*uTime + 0.2*q5);
color.y = 0.5 + 0.5*sin(0.09*n*1.5 + 0*0.7*uTime + 0.2*q6);
color.z = 0.5 + 0.5*sin(0.09*n*1.5 + 0*0.7*uTime + 0.2*q7);
float rotspeed = sin(0.02*q5);
vec2 uvrot = uv;
uvrot = vec2(cos(rotspeed)*uvrot.x - sin(rotspeed)*uvrot.y, sin(rotspeed)*uvrot.x + cos(rotspeed)*uvrot.y);
// background stars
vec3 backstars1 = backstarsf(uvrot + 0.1*uTime, 50.0 );
vec3 backstars2 = backstarsf(uvrot + 0.12*uTime, 20.0 );
vec3 backstars3 = backstarsf(uvrot + 0.14*uTime, 10.0 );
vec3 backstars4 = backstarsf(uvrot + 0.16*uTime, 7.0 );
//vec3 backstars5 = backstarsf(uvrot + 3.0*uTime, 1.0 );
float backstars = backstars1 + backstars2 + backstars3 + backstars4; // make it vec3 to add colors for the stars
backstars *= 4.0 * max(0.2, 0.05 + 0.5*min( 1.0 ,max( 0.0 ,audioMidSmooth - 1.0)*1.3));
// ### moving stars by martin ###
vec2 uv_temp = uv;
uv = uvrot;
uv-=vec2(q31,q32);
rs0.x = atan(uv.x, uv.y)/3.1416*2;
rs0.y = .05/(length (uv));
rss = vec2 (rs0.x,rs0.y + q10 + uTime*0.1);
rss = multiply(rss,mat2(.7,.7,-.7,.7));
float noise = (texture(sampler_pw_noise_lq,rss / 32.0)-.7 >= 0);
rss = abs(fract(rss * 8.0)-0.5);
vec3 dots = 0;
dots = clamp01(.06/length(rss)) *noise;
rss = vec2 (rs0.x * 2.0,rs0.y + q11 + uTime*0.05);
rss = multiply(rss,mat2(.7,.7,-.7,.7));
noise = (texture(sampler_pw_noise_lq,rss / 32.0)-.7 >= 0);
rss = abs(fract(rss * 8.0)-.5);
dots += clamp01(.04/length(rss)) * noise;
dots *= clamp01(.04/abs(.01/rs0.y - 0.0))+.0;
dots *= dots;
// ### End of stars ###
float angle = atan(z.x, z.y);
if(m == 1) // inside of the mandelbrot set
{
ret = col;
float q = smoothstep(1.6, 0.0 ,fraciter) * 3.0; // darker leaves
ret *= q;
//ret *= 1.0 + smoothstep(0.5,0.1,fraciter) * 3.0;
ret *= 1.0 + sin(angle * 2.0 + leaves * 2.0) * 3.0; // add lines to the leaves, multiply the angle for more leaves
}
else // outside of the mandelbrot set
{
ret = 0;
vec2 sunpos = vec2(q31,q32);
float circle = Dist(uv,sunpos);
float circler = 0.17;
ret += dots;
ret += backstars;
if(circle < circler) // add sun
{
vec3 sun = 4.0 * texture(sampler_sun, (uv*uTexSize.xy + 0.5*uFrame)*texsize_sun.zw).xyz;
sun *= 0.9*smoothstep(circler,circler-0.045, circle);
ret += vec3( 1.0 ,0.8, 0.0 )*sun*0.8;
ret += sun*0.16*vec3(0.8, 1.0 ,3.0 * (q1+q2+q3));
}
ret += 0.2*vec3(0.4*(q1+q2+q3),0.2, 1.0 )*smoothstep(circler+0.5, circler, circle);
}
uv = uv_temp;
//if(sqrt(uv.x*uv.x + uv.y*uv.y)<0.05) {ret = 1;}
//ret*=1.6;
//uv-=0.5;
//ret = vec3(uv.x,uv.y, 0.0 );
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  sampler sampler_sun;
vec4 texsize_sun;
sampler sampler_colors14;
